using SoulsFormats;using System.Text.Json;using System.Security.Cryptography;

string sourceRoot=args[0],nativeRoot=args[1],output=args[2],defs=args[3];var hashes=new Dictionary<string,string>();
byte[] Read(string root,string path){string full=Path.Combine(root,path);var bytes=File.ReadAllBytes(full);hashes[full]=Convert.ToHexStringLower(SHA256.HashData(bytes));return bytes;}
byte[]? Source(string p)=>File.Exists(Path.Combine(sourceRoot,p))?Read(sourceRoot,p):null;byte[]? Native(string p)=>File.Exists(Path.Combine(nativeRoot,p))?Read(nativeRoot,p):null;
void Check(bool ok,string why){if(!ok)throw new InvalidDataException(why);}void Reject(Action action,string why){try{action();}catch(InvalidDataException){return;}throw new Exception("Accepted invalid "+why);}
string Leaf(string p)=>p.Replace('\\','/').Split('/').Last();var json=new JsonSerializerOptions{WriteIndented=true,IncludeFields=true};string Data(object o)=>JsonSerializer.Serialize(o,o.GetType(),json);
var map=MSB1.Read(Source("map/MapStudio/m13_00_00_00.msb")!);var sourceBytes=map.Write();
var bindings=map.Parts.GetEntries().Where(p=>p is MSB1.Part.MapPiece or MSB1.Part.Object or MSB1.Part.Collision or MSB1.Part.Enemy).Select(p=>new EnvironmentBinding(p.Name,p.LightID,p.FogID,p.ScatterID,p.ShadowID,p is MSB1.Part.Collision,p.ToneMapID,p.ToneCorrectID)).ToArray();
var environment=MapEnvironment.Load(Source,Native,"DS1R","m13_00_00_00","m40_05_00_00",defs,bindings,nativeTemplateMap:"m24_01_00_00");CatacombsEnvironment.Apply(environment,Source,defs);
var oldBindings=environment.Bindings.ToDictionary(p=>p.Key,p=>p.Value.DeepCopy());var oldFiles=environment.Files.ToDictionary(f=>f.Path,f=>f.Bytes.ToArray());var oldRows=environment.Rows.ToList();var oldShadow=environment.ShadowBindings.ToDictionary(p=>p.Key,p=>p.Value);var oldScene=environment.SceneBindings.ToDictionary(p=>p.Key,p=>p.Value);
var choice=MapDestination.Select("additional","DS1R","m13_00_00_00","m40_05_00_00");var seeded=MapDestination.EnvironmentMaps(choice,Native("map/m24/m24_envmap.tpf.dcx")!,null);var seededBank=TPF.Read(seeded);
foreach(string name in new[]{"m40_02_GILM0000","m40_04_GILM0401"}){if(seededBank.Textures.Any(t=>t.Name==name))continue;var prior=TPF.Read(Native("map/m24/m24_envmap.tpf.dcx")!).Textures.First(t=>t.Type==TPF.TexType.Cubemap&&t.Format==100);prior.Name=name;seededBank.Textures.Add(prior);}seeded=seededBank.Write(DCX.Type.DCX_DFLT_10000_44_9);
if(args.Length>4)seeded=Read("",Path.GetFullPath(args[4]));
