var result=PinwheelEnvironment.Apply(environment,Source,Staged,defs,map);var scoped=result.Report.Parts.ToHashSet(StringComparer.Ordinal);
Check(result.Report.EnvironmentRow>=35000&&scoped.Contains("h0036B0")&&scoped.Contains("m2500B0")&&scoped.Contains("m2501B0")&&scoped.Contains("m2502B0")&&!scoped.Contains("m2600B0")&&!scoped.Contains("m9900B0"),"Arena reflection scope changed");
Check(map.Parts.Enemies.Where(p=>p.ModelName=="c3320").All(p=>scoped.Contains(p.Name)),"Arena boss or helper reflection missing");
foreach(var (name,before)in oldBindings){var after=environment.Bindings[name];Check(after.LightSetID==before.LightSetID&&after.FogParamID==before.FogParamID&&after.LightScatteringID==before.LightScatteringID,"Source direct/fog/scattering changed: "+name);Check(after.EnvMapID==(scoped.Contains(name)?result.Report.EnvironmentRow:before.EnvMapID),"Unowned binding changed or arena capture missing: "+name);}
Check(oldScene.All(p=>environment.SceneBindings[p.Key]==p.Value)&&oldShadow.All(p=>environment.ShadowBindings[p.Key]==p.Value),"Source tone/shadow bindings changed");
int profiles=0,priorValues=0;
void Profile(byte[] before,byte[] after){var a=GPARAM.Read(before);var b=GPARAM.Read(after);Check(a.Params.Count==b.Params.Count,"GPARAM group count changed");
 for(int group=0;group<a.Params.Count;group++){Check(a.Params[group].Key==b.Params[group].Key&&a.Params[group].Fields.Count==b.Params[group].Fields.Count,"GPARAM field identity changed");for(int field=0;field<a.Params[group].Fields.Count;field++){var x=a.Params[group].Fields[field];var y=b.Params[group].Fields[field];Check(x.Key==y.Key&&x.GetType()==y.GetType(),"GPARAM ABI changed");foreach(var value in x.Values){Check(Data(value)==Data(y.Values.Single(v=>v.ID==value.ID)),"Prior environment value changed: "+a.Params[group].Key+"/"+x.Key+"/"+value.ID);priorValues++;}Check(y.Values.Count==x.Values.Count+(a.Params[group].Key=="Env Map:Editor"?1:0),"Unrelated GPARAM row added");}}
 foreach(var old in a.UnkParamExtras)Check(b.UnkParamExtras.Single(e=>e.GroupIndex==old.GroupIndex).Ids.Take(old.Ids.Count).SequenceEqual(old.Ids),"Historical environment index changed");
 var env=b.Params.Single(p=>p.Key=="Env Map:Editor");int row=result.Report.EnvironmentRow;Check(((GPARAM.UintField)env.Fields.Single(f=>f.Key=="Env Map: EnvMapId")).Values.Single(v=>v.ID==row).Value==501,"Wrong arena texture selector");Check(((GPARAM.FloatField)env.Fields.Single(f=>f.Key=="Env Map: ColorScale")).Values.Single(v=>v.ID==row).Value==1,"Arena reflection applies guessed gain");Check(b.UnkParamExtras.Single(e=>e.GroupIndex==b.Params.IndexOf(env)).Ids.Contains(row),"Arena row absent from native GPARAM index");profiles++;
}
foreach(var file in environment.Files){if(file.Path.EndsWith(".gparambnd.dcx",StringComparison.Ordinal)){var a=BND4.Read(oldFiles[file.Path]);var b=BND4.Read(file.Bytes);Check(a.Files.Count==b.Files.Count,"Native phase binder entries changed");foreach(var f in a.Files)Profile(f.Bytes.ToArray(),b.Files.Single(n=>n.ID==f.ID&&n.Name==f.Name).Bytes.ToArray());}else Profile(oldFiles[file.Path],file.Bytes);}
var original=TPF.Read(seeded);var nativeBank=TPF.Read(result.Files[PinwheelEnvironment.TexturePath]);
byte[] Record(TPF owner,TPF.Texture t){var one=new TPF{Platform=owner.Platform,Encoding=owner.Encoding,Flag2=owner.Flag2};one.Textures.Add(t);return one.Write();}
Check(nativeBank.Textures.Count==original.Textures.Count+1,"Arena reflection did not append exactly one cube");foreach(var t in original.Textures)Check(Record(original,t).AsSpan().SequenceEqual(Record(nativeBank,nativeBank.Textures.Single(n=>n.Name==t.Name))),"Previous native/imported cube changed: "+t.Name);
var split=BXF3.Read(Source("map/m13/GI_EnvM_m13.tpfbhd")!,Source("map/m13/GI_EnvM_m13.tpfbdt")!);var sourceCube=TPF.Read(split.Files.Single(f=>Leaf(f.Name)==result.Report.SourceCapture).Bytes.ToArray()).Textures.Single(t=>t.Name==result.Report.SourceCube);var cube=nativeBank.Textures.Single(t=>t.Name==PinwheelEnvironment.TextureName);
var from=sourceCube.HeaderizeExt(out var ext);var to=cube.HeaderizeExt(out var nativeExt);var sh=new DDS(from);var nh=new DDS(to);
Check(ext==".dds"&&nativeExt==".dds"&&cube.Format==100&&cube.Header.DXGIFormat==95&&cube.Type==TPF.TexType.Cubemap&&cube.Header.TextureCount==6&&sh.dwWidth==256&&sh.dwHeight==256&&sh.dwMipMapCount==8&&nh.dwWidth==256&&nh.dwHeight==256&&nh.dwMipMapCount==8,"Arena BC6H cube metadata changed");
int sourceAt=sh.DataOffset,nativeAt=nh.DataOffset,blocks=0;for(int face=0;face<6;face++)for(int mip=0;mip<8;mip++){int dim=Math.Max(1,256>>mip),bytes=((dim+3)/4)*((dim+3)/4)*16;Check(from.AsSpan(sourceAt,bytes).SequenceEqual(to.AsSpan(nativeAt,bytes)),"Arena cube face/mip payload changed");sourceAt+=bytes;nativeAt+=bytes;blocks+=bytes/16;}Check(sourceAt==from.Length&&nativeAt==to.Length,"Unexpected source/native DDS tail");
EnvironmentResult Fresh()=>new(oldBindings.ToDictionary(p=>p.Key,p=>p.Value.DeepCopy()),oldFiles.Select(p=>new EnvironmentFile(p.Key,p.Value.ToArray())).ToList(),oldRows.ToList(),[]);
Reject(()=>PinwheelEnvironment.Apply(environment,Source,Staged,defs,map),"duplicate arena reflection");
var occupied=Fresh();Reject(()=>PinwheelEnvironment.Apply(occupied,Source,p=>p==PinwheelEnvironment.TexturePath?result.Files[p]:Native(p),defs,map),"occupied arena cube");Check(occupied.Files.All(f=>f.Bytes.AsSpan().SequenceEqual(oldFiles[f.Path]))&&occupied.Bindings.All(p=>p.Value.EnvMapID==oldBindings[p.Key].EnvMapID),"Failed conversion changed environment");
var changed=MSB1.Read(sourceBytes);changed.Parts.Collisions.Single(p=>p.Name=="h0036B0").EnvLightMapSpotName="【環境ポイント】外";Reject(()=>PinwheelEnvironment.Apply(Fresh(),Source,Staged,defs,changed),"wrong authored capture");
changed=MSB1.Read(sourceBytes);changed.Parts.Enemies.Single(p=>p.EntityID==1300800).CollisionName="h0000B0";Reject(()=>PinwheelEnvironment.Apply(Fresh(),Source,Staged,defs,changed),"wrong boss floor ownership");
Check(map.Write().AsSpan().SequenceEqual(sourceBytes),"Source MSB was mutated");foreach(var (path,hash)in hashes)Check(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))==hash,"Original game archive changed: "+path);
Directory.CreateDirectory(output);foreach(var file in environment.Files){string p=Path.Combine(output,file.Path);Directory.CreateDirectory(Path.GetDirectoryName(p)!);File.WriteAllBytes(p,file.Bytes);}foreach(var (path,bytes)in result.Files){string p=Path.Combine(output,path);Directory.CreateDirectory(Path.GetDirectoryName(p)!);File.WriteAllBytes(p,bytes);}
File.WriteAllBytes(Path.Combine(output,"owned-cube.tpf.dcx"),Record(nativeBank,cube));
File.WriteAllText(Path.Combine(output,"bindings.json"),JsonSerializer.Serialize(environment.Bindings,json));
