Console.WriteLine($"PASS Pinwheel authored specular capture: 6 faces × 8 mips lossless BC6H, {profiles} profiles/{priorValues} prior values and {original.Textures.Count} shared cubes unchanged, {hashes.Count} original files unchanged. Matched warm room lighting requires gameplay validation.");
